TEMPLATE = {
    'Producto Terminado / Tejido Circular': 'Producto Terminado / Tejido Circular / Industrial',
    'Producto en Proceso / No Tejido': 'Producto en Proceso / Carda',
    'Producto en Proceso / Importado': 'Producto en Proceso / Importación',
}
Categ = env['product.category'].with_context(active_test=False)
company = env['res.company'].browse(1)
Categ = Categ.with_company(company)
# Todo lo contable y de inventario de la categoría plantilla (Odoo no hereda las cuentas del padre).
COPIAR = ['property_account_income_categ_id', 'property_account_expense_categ_id', 'property_valuation',
          'property_cost_method', 'property_stock_journal', 'property_stock_valuation_account_id',
          'property_price_difference_account_id', 'account_stock_variation_id',
          'property_stock_account_production_cost_id', 'removal_strategy_id', 'packaging_reserve_method']
prop_fields = [f for f in COPIAR if f in Categ._fields]
faltan = [f for f in Categ._fields if (f.startswith('property_') or 'account' in f) and f not in prop_fields
          and Categ._fields[f].store is not False and Categ._fields[f].type in ('many2one', 'selection')]
if faltan:
    print('OJO: campos contables que no se copian, revisar:', faltan)

def by_name(name):
    return Categ.search([('complete_name', '=', name)], limit=1)

def plantilla(path):
    for pref, tpl in TEMPLATE.items():
        if path == pref or path.startswith(pref + ' / '):
            c = by_name(tpl)
            if c:
                return c
    parts = path.split(' / ')
    while parts:
        c = by_name(' / '.join(parts))
        if c:
            return c
        parts.pop()
    return Categ.browse()

creadas, cache = [], {}
def asegurar(path):
    if path in cache:
        return cache[path]
    c = by_name(path)
    if not c:
        parts = path.split(' / ')
        parent = asegurar(' / '.join(parts[:-1])) if len(parts) > 1 else Categ.browse()
        tpl = plantilla(path)
        vals = {'name': parts[-1], 'parent_id': parent.id or False}
        for f in prop_fields:
            v = tpl[f] if tpl else False
            vals[f] = v.id if hasattr(v, 'id') else v
        c = Categ.create(vals) if APLICAR else Categ.new(vals)
        creadas.append(path)
    cache[path] = c
    return c

Product = env['product.product'].with_context(active_test=False).with_company(company)
movidos, saltados = 0, []
for pid, path in DATA['mover'].items():
    p = Product.browse(int(pid)).exists()
    if not p:
        saltados.append((pid, 'no existe')); continue
    dest = asegurar(path)
    o, d = p.categ_id, dest
    cambia = (o.property_stock_valuation_account_id != d.property_stock_valuation_account_id
              or o.property_valuation != d.property_valuation or o.property_cost_method != d.property_cost_method)
    if p.qty_available and cambia:
        saltados.append((p.default_code, 'tiene existencia y cambia cuenta o método de inventario: moverlo con Contabilidad'))
        continue
    if APLICAR:
        p.product_tmpl_id.categ_id = dest.id
    movidos += 1

archivados, no_arch = 0, []
for pid in DATA['archivar']:
    p = Product.browse(pid).exists()
    if not p or not p.active:
        continue
    if p.qty_available or env['stock.quant'].sudo().search_count([('product_id', '=', p.id), ('quantity', '!=', 0)]):
        no_arch.append(p.default_code); continue
    if APLICAR:
        tmpl = p.product_tmpl_id
        if len(tmpl.with_context(active_test=False).product_variant_ids) == 1:
            tmpl.active = False
        else:
            p.active = False
    archivados += 1

print('Categorías nuevas:', len(creadas)); [print('  ', c) for c in creadas]
print('Productos movidos:', movidos, '| saltados:', len(saltados)); [print('  ', s) for s in saltados[:50]]
print('Archivados:', archivados, '| no archivados por existencia:', len(no_arch), no_arch[:30])
if APLICAR:
    env.cr.commit(); print('COMMIT hecho')
else:
    env.cr.rollback(); print('Simulación: no se escribió nada')
